def _gql(token, q):
    req = urllib.request.Request("https://api.github.com/graphql",
        data=json.dumps({"query": q}).encode(),
        headers={"Authorization": "bearer " + token, "Content-Type": "application/json",
                 "User-Agent": "quill-dashboard"})
    with urllib.request.urlopen(req, timeout=25) as r:
        j = json.loads(r.read().decode())
    if "errors" in j:
        raise RuntimeError(str(j["errors"])[:300])
    return j["data"]

def _fetch(token, since, d30, d60):
    base = "repo:%s is:pr is:merged" % REPO
    specs = []
    for i, lg in enumerate(COHORT):
        specs += [(i,"merged","%s author:%s merged:>=%s"%(base,lg,since)),
                  (i,"feat","%s author:%s feat in:title merged:>=%s"%(base,lg,since)),
                  (i,"fix","%s author:%s fix in:title merged:>=%s"%(base,lg,since)),
                  (i,"reviews","%s reviewed-by:%s merged:>=%s"%(base,lg,since)),
                  (i,"d30","%s author:%s merged:>=%s"%(base,lg,d30)),
                  (i,"d60","%s author:%s merged:>=%s"%(base,lg,d60))]
        for sname,kw in SURFACES:
            specs.append((i,"fp:"+sname,"%s author:%s %s in:title merged:>=%s"%(base,lg,kw,since)))
    raw = {lg: {} for lg in COHORT}
    CH = 30
    for c in range(0, len(specs), CH):
        chunk = specs[c:c+CH]
        parts = ['a%d: search(query:%s, type:ISSUE){issueCount}' % (j, json.dumps(q))
                 for j,(i,m,q) in enumerate(chunk)]
        data = _gql(token, "query{" + " ".join(parts) + "}")
        for j,(i,m,q) in enumerate(chunk):
            raw[COHORT[i]][m] = data["a%d"%j]["issueCount"]
    tot = _gql(token, 'query{t: search(query:%s, type:ISSUE){issueCount}}'
               % json.dumps("%s merged:>=%s" % (base, since)))
    return raw, tot["t"]["issueCount"]

def _gh(lg, since, extra=""):
    q = ("repo:%s is:pr is:merged author:%s merged:>=%s %s" % (REPO, lg, since, extra)).strip()
    return "https://github.com/search?type=pullrequests&q=" + q.replace(" ", "+").replace(":", "%3A")
def _ghrev(lg, since):
    q = "repo:%s is:pr is:merged reviewed-by:%s merged:>=%s" % (REPO, lg, since)
    return "https://github.com/search?type=pullrequests&q=" + q.replace(" ", "+").replace(":", "%3A")

def compute(raw, total, since, days):
    R = {}
    for lg, d in raw.items():
        m = max(d.get("merged",0),0)
        if m == 0:   # skip inactive
            continue
        feat=d.get("feat",0); fix=d.get("fix",0); rv=d.get("reviews",0)
        d30=d.get("d30",0); d60=d.get("d60",0)
        fp=sorted([(k.split("fp:",1)[1],v) for k,v in d.items() if k.startswith("fp:") and v>0], key=lambda x:-x[1])[:6]
        R[lg]=dict(merged=m,feat=feat,fix=fix,reviews=rv,d30=d30,d60=d60,footprint=fp,
                   maint=max(m-feat-fix,0), feat_ratio=feat/m, fix_ratio=fix/m, review_ratio=rv/m)
    keys=list(R.keys())
    def z(f):
        vals=[R[k][f] for k in keys]; mu=statistics.mean(vals); sd=statistics.pstdev(vals) or 1
        return {k:(R[k][f]-mu)/sd for k in keys}
    Z={f:z(f) for f in ["merged","feat","feat_ratio","fix","fix_ratio","reviews","review_ratio","maint"]}
    sc=lambda v:max(0,min(100,round(50+12.5*v)))
    eng={}
    for k in keys:
        dims={"Quality":sc(0.6*Z["fix_ratio"][k]+0.4*Z["fix"][k]),
              "Users":sc(0.6*Z["feat"][k]+0.4*Z["feat_ratio"][k]),
              "Impact":sc(Z["merged"][k]),
              "Leverage":sc(0.5*Z["reviews"][k]+0.5*Z["maint"][k]),
              "Leadership":sc(0.6*Z["reviews"][k]+0.4*Z["review_ratio"][k])}
        eng[k]=dict(login=k,**META[k],**R[k],dims=dims,quill=round(statistics.mean(dims.values())))
    ranked=sorted(eng.values(), key=lambda d:-d["quill"])
    N=len(ranked)
    rrk={e["login"]:i+1 for i,e in enumerate(sorted(ranked,key=lambda x:-x["reviews"]))}
    teamAvg={x:round(statistics.mean([e["dims"][x] for e in ranked])) for x in dims}
    teamQuill=round(statistics.mean([e["quill"] for e in ranked]))
    for b in range(0):
        pass
    def buckets(e): return [max(e["merged"]-e["d60"],0), max(e["d60"]-e["d30"],0), e["d30"]]
    for e in ranked: e["buckets"]=buckets(e)
    top5=ranked[:5]
    teamTrend=[round(statistics.mean([buckets(e)[b] for e in ranked]),1) for b in range(3)]
    top5Trend=[round(statistics.mean([buckets(e)[b] for e in top5]),1) for b in range(3)]
    def status(v): return "Breakout" if v>=40 else "Accelerating" if v>=15 else "Steady" if v>-15 else "Cooling"
    out=[]
    for i,e in enumerate(ranked):
        lg=e["login"]; m=e["merged"]; feat=e["feat"]; fix=e["fix"]; mt=e["maint"]; rv=e["reviews"]
        fr=e["feat_ratio"]; xr=e["fix_ratio"]; rr=e["review_ratio"]; per_day=m/days; pct=m/max(total,1)*100
        base=m/3.0; vel=round((e["d30"]/base-1)*100) if base else 0
        rank=i+1; pctile="Top %d%%"%round((i+0.5)/N*100); primary=max(e["dims"],key=e["dims"].get)
        drivers={
         "Quality":{"why":"Reliability investment. %d bug-fix PRs (%d%% of merged work) plus %d refactor / hardening PRs. Every PR also cleared PostHog's enforced review gate (approval ~100%%, formal change-requests ~0 across the team), so quality is measured as active hardening, not the gate."%(fix,round(xr*100),mt),
            "items":[["%d fix PRs"%fix,"Merged bug-fix / reliability changes"],["%d%% fix share"%round(xr*100),"Of merged work, devoted to correctness"],["%d maintenance PRs"%mt,"Refactors, chores, perf, tests"],["~100%% approved","Cleared enforced peer review to merge"]]},
         "Users":{"why":"User-facing delivery. %d feature PRs (%d%% of merged work) shipped to end users, in %s."%(feat,round(fr*100),e["area"]),
            "items":[["%d feature PRs"%feat,"New user-facing capabilities"],["%d%% feature share"%round(fr*100),"Of merged work reaching users"],[e["area"],"Primary product surface"],["%d merged total"%m,"All landed in production"]]},
         "Impact":{"why":"Scale of change that shipped. %d merged PRs in %d days (~%.1f/day) = %.1f%% of the repo's %d merged PRs. Band: %s of the active cohort."%(m,days,per_day,pct,total,pctile),
            "items":[["%d merged PRs"%m,"Shipped & reviewed"],["%.1f PRs/day"%per_day,"Sustained throughput"],["%.1f%% of repo"%pct,"Share of all merged PRs"],[pctile,"Cohort contribution band"]]},
         "Leverage":{"why":"Compounding value. %d reviews on teammates' merged PRs that unblock others, plus %d refactor / infra PRs that pay forward."%(rv,mt),
            "items":[["%d reviews given"%rv,"Unblocks others' delivery"],["%d maintenance PRs"%mt,"Refactor/infra that compounds"],["%.1fx reviews/own PR"%rr,"Leverage beyond own output"],["Force-multiplier","Value beyond own commits"]]},
         "Leadership":{"why":"Elevating others. %d reviews of teammates' work (%.1fx own output), #%d of %d reviewers in the cohort."%(rv,rr,rrk[lg],N),
            "items":[["%d reviews given"%rv,"On others' merged PRs"],["#%d reviewer"%rrk[lg],"Of %d active engineers"%N],["%.1fx own output"%rr,"Invests in others vs self"],["Mentorship","Shapes what merges"]]},
        }
        gaps=sorted(e["dims"].items(),key=lambda kv:-(kv[1]-50))
        strong=", ".join("%s (+%d)"%(k2,v-50) for k2,v in gaps[:3] if v>=50) or "balanced across drivers"
        vlab="accelerating sharply" if vel>=40 else "accelerating" if vel>=15 else "steady" if vel>-15 else "cooling (shifting toward advisory work)"
        summ=("%s ranks #%d with a QUILL of %d (team avg 50). Biggest differentiators vs baseline: %s. Over %d days: %d merged PRs (~%.1f/day), %d features, %d fixes, %d reviews given on teammates' PRs (%.1fx own output). 30-day run-rate is %s (%+d%% vs the 90-day average)."
              %(e["name"],rank,e["quill"],strong,days,m,per_day,feat,fix,rv,rr,vlab,vel))
        insights=[["Merged PRs",str(m),"Reviewed & shipped"],["Features",str(feat),"User-facing PRs"],["Fixes",str(fix),"Reliability PRs"],
                  ["Reviews given",str(rv),"On teammates' PRs"],["Maintenance",str(mt),"Refactor / chore / perf"],
                  ["Feature share","%d%%"%round(fr*100),"Work reaching users"],["Reviews / PR","%.1fx"%rr,"Leverage beyond own"],["Repo share","%.1f%%"%pct,"Of all merged PRs"]]
        ownership=[[e["area"].split("·")[0].strip(),"Primary product surface",feat,"feat PRs"],
                   ["Reliability","Bug-fix & hardening footprint",fix,"fix PRs"],
                   ["Review footprint","Teammates' PRs reviewed",rv,"reviews"]]
        ev=[["Features","%d feature PRs shipped to users"%feat,"Users",_gh(lg,since,"feat in:title")],
            ["Fixes","%d reliability / bug-fix PRs"%fix,"Quality",_gh(lg,since,"fix in:title")],
            ["Reviews","%d reviews on teammates' merged PRs"%rv,"Leadership",_ghrev(lg,since)],
            ["All merged","%d merged PRs in the window"%m,"Impact",_gh(lg,since)]]
        if lg in EXAMPLE:
            n,t=EXAMPLE[lg]; ev.insert(0,["Example PR",t,"Impact","https://github.com/%s/pull/%d"%(REPO,n)])
        out.append(dict(id=lg,rank=rank,name=e["name"],handle=lg,role=e["area"],
            avatar="https://avatars.githubusercontent.com/u/%d?s=160&v=4"%e["id"],
            quill=e["quill"],percentile=pctile,velocity=vel,primaryDriver=primary,status=status(vel),est=False,
            scores=e["dims"],buckets=e["buckets"],summary=summ,drivers=drivers,insights=insights,
            ownership=ownership,events=ev,networkCore=e["area"].split("·")[0].strip(), footprint=e.get("footprint",[]),
            metrics=dict(merged=m,feat=feat,fix=fix,maint=mt,reviews=rv,featShare=round(fr*100),
                         fixShare=round(xr*100),reviewRatio=round(rr,1),perDay=round(per_day,1),
                         reviewRank=rrk[lg],cohort=N)))
    return dict(engineers=out,teamAvg=teamAvg,teamQuill=teamQuill,teamTrend=teamTrend,top5Trend=top5Trend,
                window=dict(since=since,until=datetime.utcnow().strftime("%Y-%m-%d"),days=days,repo=REPO,
                            total_merged_prs=total,cohort=len(out)))

def build():
    token=os.environ.get("GITHUB_TOKEN")
    today=datetime.utcnow().date()
    since=(today-timedelta(days=90)).isoformat()
    d30=(today-timedelta(days=30)).isoformat(); d60=(today-timedelta(days=60)).isoformat()
    if token:
        try:
            raw,total=_fetch(token,since,d30,d60)
            p=compute(raw,total,since,90)
            p["source"]="live"; p["computedAt"]=datetime.utcnow().isoformat()+"Z"
            return p
        except Exception as ex:
            p=dict(SNAPSHOT); p["source"]="snapshot"; p["error"]=str(ex)[:160]; return p
    p=dict(SNAPSHOT); p["source"]="snapshot"; return p

class handler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            payload=build()
        except Exception as ex:
            payload=dict(SNAPSHOT); payload["source"]="snapshot"; payload["error"]=str(ex)[:160]
        body=json.dumps(payload).encode()
        self.send_response(200)
        self.send_header("content-type","application/json")
        self.send_header("cache-control","s-maxage=1800, stale-while-revalidate=86400")
        self.send_header("access-control-allow-origin","*")
        self.end_headers(); self.wfile.write(body)
